#include <bits/stdc++.h>
using namespace std;

int countSmaller(const vector<int>& arr, int startIdx, int val) {
    int count = 0;
    for (int i = startIdx; i < (int)arr.size() && arr[i] < val; i++) {
        count++;
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<int> positionsV, positionsK, positionsX;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'V') {
            positionsV.push_back(i);
        } else if (s[i] == 'K') {
            positionsK.push_back(i);
        } else {
            positionsX.push_back(i);
        }
    }
    int countV = (int)positionsV.size();
    int countK = (int)positionsK.size();
    int countX = (int)positionsX.size();

    const long long INF = LLONG_MAX;
    vector<vector<vector<vector<long long>>>> dp(
        countV + 1,
        vector<vector<vector<long long>>>(
            countK + 1,
            vector<vector<long long>>(
                countX + 1,
                vector<long long>(2, INF)
            )
        )
    );

    dp[0][0][0][0] = 0;

    for (int vCount = 0; vCount <= countV; vCount++) {
        for (int kCount = 0; kCount <= countK; kCount++) {
            for (int xCount = 0; xCount <= countX; xCount++) {
                for (int t = 0; t < 2; t++) {
                    long long current = dp[vCount][kCount][xCount][t];
                    if (current == INF) continue;
                    if (vCount < countV) {
                        int vv = positionsV[vCount];
                        int moves = countSmaller(positionsV, vCount, vv)
                                    + countSmaller(positionsK, kCount, vv)
                                    + countSmaller(positionsX, xCount, vv);
                        if (dp[vCount + 1][kCount][xCount][1] > current + moves) {
                            dp[vCount + 1][kCount][xCount][1] = current + moves;
                        }
                    }
                    if (kCount < countK && t == 0) {
                        int kk = positionsK[kCount];
                        int moves = countSmaller(positionsV, vCount, kk)
                                    + countSmaller(positionsK, kCount, kk)
                                    + countSmaller(positionsX, xCount, kk);
                        if (dp[vCount][kCount + 1][xCount][0] > current + moves) {
                            dp[vCount][kCount + 1][xCount][0] = current + moves;
                        }
                    }
                    if (xCount < countX) {
                        int xx = positionsX[xCount];
                        int moves = countSmaller(positionsV, vCount, xx)
                                    + countSmaller(positionsK, kCount, xx)
                                    + countSmaller(positionsX, xCount, xx);
                        if (dp[vCount][kCount][xCount + 1][0] > current + moves) {
                            dp[vCount][kCount][xCount + 1][0] = current + moves;
                        }
                    }
                }
            }
        }
    }

    long long answer = INF;
    for (int i = 0; i < 2; i++) {
        if (dp[countV][countK][countX][i] < answer) {
            answer = dp[countV][countK][countX][i];
        }
    }
    cout << answer << "\n";

    return 0;
}
